-- KB-MOCK (vain paikalliseen testaukseen): kb-skeemojen sarakkeet vastaavat tuotannon kb-skeemaa (SELECT-tarkistus 16.10.2026).
-- Tuotteet/hinnat/variantit on kopioitu kb:stä (yritystietoa, ei henkilötietoja). EI AJETA TUOTANTOON.
create schema if not exists kb;
create table kb.locations (
  id bigint generated always as identity primary key, business_id bigint, name text not null,
  location_type text not null default 'site' check (location_type in ('site','sauna','treatment_sauna','pool','building','outdoor','parking','other')),
  parent_location_id bigint references kb.locations(id), description text, active boolean not null default true,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table kb.products (
  id bigint generated always as identity primary key, business_id bigint not null default 1, external_system text, external_id text, slug text,
  name text not null, name_en text,
  category text not null check (category in ('public_sauna','treatment','ritual','private_sauna','ceremony','event','training','gift_card','season_card','add_on','product_rental','corporate','other')),
  description text, description_en text, language text not null default 'fi',
  price numeric, price_type text check (price_type in ('fixed','per_person','from','per_hour','per_unit','base_plus_extra_person','deposit','variable')),
  price_text text, currency text not null default 'EUR', vat_rate numeric, price_includes_vat boolean, included_persons integer, extra_person_price numeric,
  duration_minutes integer, duration_text text, capacity_min integer, capacity_max integer,
  location_id bigint references kb.locations(id), includes_smoke_sauna boolean, valid_from date, valid_to date, booking_url text,
  confidence text not null default 'high', needs_review boolean not null default false, review_note text, active boolean not null default true,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table kb.product_price_variants (
  id bigint generated always as identity primary key, product_id bigint not null references kb.products(id), label text not null, price numeric not null,
  currency text not null default 'EUR', duration_minutes integer, weekdays smallint[], time_start time, time_end time, included_persons integer,
  extra_person_price numeric, persons_min integer, persons_max integer, valid_from date, valid_to date, notes text,
  confidence text not null default 'medium', needs_review boolean not null default false, review_note text, active boolean not null default true,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table kb.change_log (
  id bigint generated always as identity primary key, table_name text not null, row_id bigint, action text not null,
  actor text default current_user, old_data jsonb, new_data jsonb, changed_at timestamptz not null default now());
alter table kb.locations enable row level security;
alter table kb.products enable row level security;
alter table kb.product_price_variants enable row level security;
alter table kb.change_log enable row level security;




select setval(pg_get_serial_sequence('kb.products','id'), (select max(id) from kb.products));
select setval(pg_get_serial_sequence('kb.product_price_variants','id'), (select max(id) from kb.product_price_variants));
select setval(pg_get_serial_sequence('kb.locations','id'), (select max(id) from kb.locations));

-- Myöhemmät migraatiot lukevat näitä tuotannon kb-tauluja (tekstirekisteri, kuitti, päivänäkymä).
-- Mockissa ne ovat tyhjiä paitsi yritysrivi, jota booking_29 kopioi settings.selleriin. EI tuotantoon.
alter table kb.locations
  add column if not exists language text,
  add column if not exists directions text,
  add column if not exists parking text,
  add column if not exists public_transport text,
  add column if not exists accessibility text;
create table if not exists kb.faq (
  id bigint generated always as identity primary key,
  question text, answer text, language text, category text, active boolean not null default true
);
create table if not exists kb.policies (
  id bigint generated always as identity primary key,
  title text, body text, language text, status text, internal boolean not null default false
);
-- kb.policies.category (tuotannossa text not null): tarvitaan kb_policies_en_source-migraation (20261024123109) rekisteröintiehdossa
alter table kb.policies add column if not exists category text;
create table if not exists kb.opening_hours (
  id bigint generated always as identity primary key,
  session_name text, swimsuit_rule text, language text, active boolean not null default true
);
create table if not exists kb.event_dates (
  id bigint generated always as identity primary key,
  product_id bigint references kb.products(id),
  starts_on date, ends_on date, time_text text, active boolean not null default true
);
create table if not exists kb.businesses (
  id bigint primary key,
  legal_name text, trade_name text, business_id text,
  street_address text, postal_code text, city text, country text,
  email text, phone text, website text,
  description text, language text, active boolean not null default true,
  updated_at timestamptz not null default now()
);
