insert into kb.locations(id,name,location_type,parent_location_id,description) overriding system value values
(2,'Savusauna (maasavusauna)','sauna',1,'Maan sisälle rakennettu savusauna, joka jättää erityisen puhdistuneen ja raikkaan olon. Valmistui vuonna 2021. Vanhan sivuston mukaan yksi harvoista vuoden jokaisena päivänä lämpiävistä savusaunoista.'),
(3,'Hoitosauna Rauni','treatment_sauna',1,'Sauna-alueella sijaitseva hoito-/saunotussauna, jossa kaikki saunahoidot, saunotukset ja saunarituaalit toteutetaan (omistajan päätös 9.10.2026). Leveät lauteet. Saunan edustalla pieni alue viilentymi'),
(4,'Kylmä- ja lämminvesialtaat','pool',1,'Saunan edustalla kylmävesiallas ja lämminvesiallas (palju). Altaiden lämpötila vaihtelee jonkin verran sääolosuhteiden mukaan. Lämpimästä altaasta näkymä Sipoonjokilaaksoon ja vanhaan metsään. Pääsy a'),
(5,'Hirsimökki','building',1,'Sauna-alueella sijaitseva hirsimökki, jossa suihku. Mökin lähistöllä perinteinen huussi.'),
(6,'Laavu','outdoor',1,'Laavu on asiakkaiden vapaasti käytettävissä sauna-ajan puitteissa; omia makkaroita voi paistaa. Jälkilöylyjen alussa laavulla voi olla vielä yleisen vuoron asiakkaita klo 19–20.'),
(7,'Hoitosauna Lovi','treatment_sauna',1,'Vanha, hyvin pieni hoitosauna sauna-alueella. Ei enää käytössä saunahoidoissa – kaikki hoidot tehdään hoitosauna Raunissa (omistajan päätös 9.10.2026). Vanhoissa teksteissä taivutusmuodot ''Lovessa''/''L'),
(1,'Sipoonjoen perinnesauna','site',1,'Sauna-alue Sipoonjoen rannalla Sipoon Hindsbyssä, Sipoonkorven kansallispuiston kupeessa. Alueella liikutaan osittain ulkona ympäri vuoden. Alueella mm. savusauna, hoitosauna Rauni, kylmä- ja lämminve');
insert into kb.products(id,external_system,external_id,slug,name,name_en,category,description,description_en,price,price_type,price_text,vat_rate,included_persons,extra_person_price,duration_minutes,duration_text,capacity_min,capacity_max,location_id,includes_smoke_sauna,active) overriding system value values
(1,'johku','132','yleinensauna','Yleinen vuoro (to, la-su)','Public sauna (Sat & Sun)','public_sauna','Sekavuoro, johon kaikki ovat tervetulleita. Sisältää pääsyn sauna-alueelle, kylmä- ja lämminvesialtaisiin sekä laavulle sauna-ajan puitteissa. Viikonloppuisin (la ja su) yleinen vuoro on klo 14–19 ja saunomisaika kaksi tuntia, paikka on aina varattava etukäteen ja saunotaan uima-asussa. Kuumista löylyistä pitävän kannattaa tulla ensimmäisille vuoroille, pehmeämpien löylyjen ystävän viimeiselle vuorolle tai jälkilöylyille. Torstaisin yleinen vuoro klo 17–19. Tuo oma pyyhe ja tossut (vuokraus paikan päällä 5 €). Hirsimökissä suihku, lähellä huussi.',null,29.0,'per_person','29,00 € / hlö',25.5,null,null,120,'la–su klo 14–19 (saunomisaika 2 h); to klo 17–19',null,null,2,true,true),
(2,'johku','32','miestensauna-2','Miesten sauna (ma)','Men''s sauna (Mon)','public_sauna','Maanantaisin miesten vuoro klo 16–19 (3 h). Voit saapua oman aikataulusi mukaan klo 16 jälkeen. Sisältää pääsyn sauna-alueelle, kylmä- ja lämminvesialtaisiin sekä laavun käytön; makkaroita voi paistaa. Uima-asu on vapaaehtoinen. Tuo oma pyyhe ja tossut tai vuokraa paikan päältä (5 €/kpl). Talvella suositellaan saunatakkia ja saunahattua tai pipoa.',null,29.0,'per_person','29,00 € / hlö',25.5,null,null,180,'ma klo 16–19',null,null,2,true,true),
(3,'johku','9','naistensauna','Naisten sauna (ti)','Women''s sauna (Tue)','public_sauna','Tiistait on pyhitetty naisille: naisten vuoro klo 16–19 (3 h). Sisältää pääsyn sauna-alueelle, kylmä- ja lämminvesialtaisiin sekä laavun ja hirsimökin käytön. Uima-asu on vapaaehtoinen. Tuo oma pyyhe ja tossut tai vuokraa paikan päältä (5 €/kpl). Jos toivot naispuolista saunottajaa hoitoon, suositellaan varaamaan hoito tiistain naisten vuoron yhteyteen.',null,29.0,'per_person','29,00 € / hlö',25.5,null,null,180,'ti klo 16–19',null,null,2,true,true),
(4,'johku','61','hiljainen-sauna','Hiljainen sauna (ke)','Silent sauna (Wed)','public_sauna','Keskiviikkoisin hiljainen sekavuoro klo 16–19 (3 h): puhelimet ja keskustelut jäävät saunan ulkopuolelle, kuulumisia voi vaihtaa laavulla tai terassilla. Voit saapua klo 16 jälkeen oman aikataulusi mukaan. Sisältää pääsyn sauna-alueelle, kylmä- ja lämminvesialtaisiin ja laavulle. Uima-asu on vapaaehtoinen. Pyyhe ja tossut omat tai vuokralla (5 €/kpl).',null,29.0,'per_person','29,00 € / hlö',25.5,null,null,180,'ke klo 16–19',null,null,2,true,true),
(5,'johku','120','turvetorstai','Turvetorstai (to)','Peat Thursday','public_sauna','Turvesaunavuoro torstaisin klo 16–19 (3 h). Vuoro alkaa klo 16 omatoimisella saunomisella; klo 16.30 alkaen saunottaja ohjaa yhteisen turveseremonian (löylyntervehdys, vihdoilla lämmittely ja opastus hoitoturpeen käyttöön). Sisältää turveseremonian, hoitoturpeen kasvoille sekä pääsyn sauna-alueelle, kylmä- ja lämminvesialtaisiin ja laavulle. Vuorolla kylvetään uima-asussa. Pyyhe ja tossut omat tai vuokralla 5 €/kpl.',null,35.0,'per_person','35,00 € / hlö',25.5,null,null,180,'to klo 16–19',1,8,2,true,true),
(6,'johku','152','tunnin-vuoro','Tunnin saunavuoro (la-su)',null,'public_sauna','Tunnin mittainen saunavuoro sekasaunassa lauantaisin ja sunnuntaisin klo 14 ja klo 18. Sisältää pääsyn sauna-alueelle, kylmä- ja lämminvesialtaisiin ja laavulle. Saunotaan uima-asussa; avoin kaikille. Paikka varattava etukäteen.',null,18.0,'per_person','18,00 € / hlö',25.5,null,null,60,'1 h, la–su klo 14 tai 18',null,null,2,true,true),
(7,'johku','179','saunarituaali-ja-savusaunavuoro','Saunarituaali ja savusaunavuoro (la & su)','Sauna Ritual & Smoke Sauna Session','ritual','Avoin saunarituaali lauantaisin ja sunnuntaisin: vuoro alkaa 20 minuutin saunotusrituaalilla hoitosauna Raunissa (pienryhmä, enintään 6 osallistujaa), josta siirrytään savusaunaan. Sisältää löylyntervehdyksen, kevyttä lämmittelyvihdontaa ja vuodenkierron mukaisen minihoidon sekä pääsyn sauna-alueelle, altaisiin ja laavulle. Rituaaliin voi tulla alasti, mutta savusaunassa ja paljuissa käytetään uima-asua. Ohjelma vaihtuu vuodenaikojen mukaan. Elämyslahjojen lahjakortilla: varaa ensin yleinen vuoro ja osta rituaali erikseen.',null,49.0,'per_person','49 € / hlö',25.5,null,null,120,'rituaali 20 min + savusauna 1 h 40 min (verkkokauppa)',1,6,3,true,true),
(8,'johku','170','saunotusrituaali','Saunotusrituaali',null,'ritual','Lyhyt saunotusrituaali hoitosauna Raunissa (enintään kuusi henkeä kerrallaan): löylyntervehdys, kevyttä lämmittelyvihdontaa ja vuodenkierron mukainen minihoito. Voi osallistua uimapuvussa tai alasti. Varattavissa lisäpalveluna yleiselle vuorolle.',null,20.0,'per_person','20,00 €',25.5,null,null,20,'20 min',1,6,3,false,true),
(9,'johku','18','perinnesaunotusilta','Perinnesaunotusilta','Traditional sauna evening','event','Saunottajan ohjaama saunaseremonia savusaunassa, jossa hyödynnetään vuodenajan antimia, kasveja, vihtoja ja saunaloitsuja; illan teema seuraa vuodenkiertoa. Sisältää pääsyn sauna-alueelle, altaisiin ja laavulle; seremonian jälkeen voi jatkaa saunomista. Järjestetään noin 1–2 kertaa kuukaudessa (syksyllä noin kerran kuussa jouluun asti). Pyyhe ja tossut omat tai pyyhe vuokralla 5 €.',null,59.0,'per_person','59,00 € / hlö',25.5,null,null,90,'1 h 30 min',1,8,2,true,true),
(10,'johku','198','saunahoito-2','Saunahoito','Sauna treatment','treatment','Lempeä mutta syvä pysähdys löylyn, lämmön ja luonnonantimien äärelle. Alkaa löylyntervehdysrituaalilla, jonka jälkeen saunottaja toteuttaa valitun hoidon: hunajahoito, vihtahoito, suolahoito tai turvehoito (valinta kassalla). Varattavissa 1–4 hengelle; sisältö mukautuu ryhmän kokoon. Hoidon hintaan ei sisälly pääsyä savusaunaan tai paljuihin (pääsyliput erikseen). Toteutetaan hoitosauna Raunissa. Saunottajat: Laura Foon, Joonas Vaarala ja Saara Mäntykoski. Hoitoon voi osallistua alasti, osittain tai kokonaan uima-asussa.',null,99.0,'base_plus_extra_person','99,00 € (sis. 1 hlö), lisähenkilöt 35,00 €/hlö',25.5,1,35.0,60,'1 h',1,4,3,false,true),
(11,'johku','201','saunotus-2','Saunotus','Sauna ritual (Saunotus)','treatment','Kahden tunnin kokonaisvaltainen saunaelämys: vihdat, kasvit, yrtit, suola ja hunaja, halutessa turvehoito; loitsuja, vihtomista, löylyn, veden ja ilman tekniikoita, kellutus viileässä altaassa ja yrttitee. Saunottaja mukauttaa voimakkuuden asiakkaan mukaan. Varattavissa 1–2 hengelle. Hoidon hintaan ei sisälly pääsyä savusaunaan tai paljuihin (pääsyliput erikseen). Toteutetaan hoitosauna Raunissa. Saunottajat: Laura Foon, Joonas Vaarala ja Saara Mäntykoski. Hoitoon voi osallistua alasti, osittain tai kokonaan uima-asussa.',null,210.0,'base_plus_extra_person','210,00 € / 2 h (sis. 1 hlö), lisähenkilö 60,00 €',25.5,1,60.0,120,'2 h',1,2,3,false,true),
(12,'johku','200','syvasaunotus','Syväsaunotus','Deep Sauna Ritual','treatment','Kolmen tunnin kokonaisvaltainen saunotusrituaali useassa vaiheessa: vihdat, kasvit, yrtit, suola, hunaja ja halutessa turve; loitsuja, rytmistä vihtomista, lämpimän ja viileän vaihtelua, kellutus viileässä altaassa. Sisältää yrttiteetä ja pientä purtavaa. Varattavissa 1–2 hengelle. Hoidon hintaan ei sisälly pääsyä savusaunaan tai paljuihin (pääsyliput erikseen). Toteutetaan hoitosauna Raunissa. Saunottajat: Laura Foon, Joonas Vaarala ja Saara Mäntykoski. Hoitoon voi osallistua alasti, osittain tai kokonaan uima-asussa.',null,290.0,'base_plus_extra_person','290,00 € (sis. 1 hlö), lisähenkilö 70,00 €',25.5,1,70.0,180,'3 h',1,2,3,false,true),
(13,'johku','178','perinnesaunotus-ryhmalle','Perinnesaunotus ryhmälle',null,'treatment','Perinnesaunottaja johdattaa ryhmän metsän ja saunan parantavaan maailmaan. Suunniteltu 3–6 hengelle; sisältö vaihtelee henkilömäärän mukaan ja voidaan räätälöidä (kerro toiveet lisätiedoissa). Kesto noin 3 h. Hinta ei sisällä pääsyä savusaunaan tai paljuihin (ostettavissa erikseen). Toteutetaan hoitosauna Raunissa.',null,499.0,'fixed','499,00 €',25.5,null,null,180,'noin 3 h',3,6,3,false,true),
(14,'johku','55','perinnevihdonta','Perinnevihdonta',null,'add_on','Syvärentoutus metsän hoitavan voiman avulla: löylyntervehdys, pitkä vihdonta ja syvärentouttava kylvetys. Ei enää tarjolla – lopetettu omistajan päätöksellä 11.',null,89.0,'fixed','89,00 €',25.5,null,null,60,'noin 60 min',null,null,3,null,false),
(15,'johku','118','perinnevihdonta-kahdelle','Perinnevihdonta kahdelle',null,'add_on','Löylyntervehdys, pitkä vihdonta ja syvärentouttava kylvetyshoito kahdelle. Ei enää tarjolla – lopetettu omistajan päätöksellä 11.10.2026.',null,180.0,'fixed','180,00 €',25.5,null,null,90,'noin 90 min',null,null,3,null,false),
(16,'johku','56','vihtahoito','Vihtahoito',null,'add_on','Vihdonta on yhdistelmä hierontaa, kasvilääkintää ja aromaterapiaa. Ei enää tarjolla – lopetettu omistajan päätöksellä 11.10.2026.',null,59.0,'fixed','59,00 €',25.5,null,null,30,'noin 30 min',null,null,3,null,false),
(17,'johku','114','vihtahoito-kahdelle','Vihtahoito kahdelle',null,'add_on','Vihtahoito ystävän tai kumppanin kanssa: hierontaa, kasvilääkintää ja aromaterapiaa. Ei enää tarjolla – lopetettu omistajan päätöksellä 11.10.2026.',null,118.0,'fixed','118,00 €',25.5,null,null,60,'noin 60 min',null,null,3,null,false),
(18,'johku','57','turvehoito-15min','Turvehoito kasvoille',null,'add_on','Niska-pää-kasvohieronta ja turvenaamio. Ei enää tarjolla – lopetettu omistajan päätöksellä 11.10.2026.',null,59.0,'fixed','59,00 €',25.5,null,null,30,'noin 30 min',null,null,3,null,false),
(19,'johku','58','turvehoito-30','Turvehoito kahdelle',null,'add_on','Kevyt niska-päähieronta ja saunottajan tekemä turvehoito kahdelle. Ei enää tarjolla – lopetettu omistajan päätöksellä 11.10.2026.',null,79.0,'fixed','79,00 €',25.5,null,null,30,'noin 30 min',null,null,3,null,false),
(20,'johku','71','turvehoito-koko-vartalo','Turvehoito koko vartalo',null,'add_on','Koko vartalon turvehoito saunottajan tekemänä ja ohjaamana. Ei enää tarjolla – lopetettu omistajan päätöksellä 11.10.2026.',null,89.0,'fixed','89,00 €',25.5,null,null,60,'noin 60 min',null,null,3,null,false),
(21,'johku','59','saunahieronta-60min','Saunahieronta - koko vartalo',null,'add_on','Hoitosaunan löylyissä kokovartalohoito yrttisuolakuorinnalla sekä kasvohieronta hunajalla. Ei enää tarjolla – lopetettu omistajan päätöksellä 11.10.2026.',null,89.0,'fixed','89,00 €',25.5,null,null,60,'noin 60 min',null,null,3,null,false),
(22,'johku','60','saunahieronta-30','Saunahieronta - niska / hartia / pää',null,'add_on','Niska-, pää- ja kasvohoito, jossa hunaja, nokkonen ja siankärsämö tehostavat hieronnan vaikutuksia. Ei enää tarjolla – lopetettu omistajan päätöksellä 11.10.202',null,59.0,'fixed','59,00 €',25.5,null,null,30,'noin 30 min',null,null,3,null,false),
(23,'johku','62','perinnesaunotus-yhdelle','Perinnesaunotus yhdelle',null,'add_on','Perinnesaunottaja johdattaa metsän ja saunan parantavaan maailmaan. Vanhan sivuston mukaan sisältää löylyntervehdyksen, yrtti-suolakuorinnan, vihdon, hunajahier',null,149.0,'fixed','149,00 €',25.5,null,null,90,'90 min',null,null,3,null,false),
(24,'johku','99','vihtahoito-opiskelijatyona','Saunahoito opiskelijatyönä',null,'treatment','Satunnainen palvelu: opiskelijoiden tekemiä saunahoitoja tarjotaan vain muutaman kerran vuodessa saunottajakoulutusten yhteydessä, erikseen ilmoitettuina päivinä – ei säännöllisesti varattavissa. Perinteinen saunahoito opiskelijahintaan: saunahierontaa, turvehoitoja ja vihdontaa; hoitoa ei voi valita, vaan se määräytyy koulutuksen teeman mukaan. Hoitajina Terve Löyly -saunottajakoulutuksen opiskelijat saunottajien opastuksessa. Hoidon hintaan ei kuulu pääsy savusaunaan tai paljuihin. Järjestetään erikseen ilmoitettuina päivinä (viimeksi 26.9.2026 klo 13–18).',null,20.0,'fixed','20,00 € / 30 min',25.5,null,null,30,'30 min',null,null,3,false,true),
(25,'johku','16','oma-saunavuoro','Oma savusaunavuoro','Private sauna session','private_sauna','Koko Sipoonjoen perinnesaunan miljöö omaan käyttöön (esim. ilta ystävien kanssa, synttärit, polttarit). Sisältää savusaunan, lämmin- ja kylmävesialtaat sekä laavun ja hirsimökin vapaan käytön. Tilat voi vuokrata ennen yleisiä vuoroja tai koko päiväksi. Hinnat ovat voimassa ainoastaan yksityishenkilöille; yrityksille omat tuotteet.',null,250.0,'from','Alkaen 250,00 € / 2 h',25.5,null,10.0,120,'1–7 h vaihtoehdot',null,null,1,true,true),
(26,'johku','15','jalkiloylyt','Savusaunan jälkilöylyt','After Session Sauna','private_sauna','Yleisten vuorojen jälkeen viipyilevät ja pehmeät jälkilöylyt omalle porukalle klo 19 alkaen klo 21 saakka viikolla ja klo 22 saakka viikonloppuisin. Sisältää savusaunan, lämmin- ja kylmävesialtaat sekä laavun vapaan käytön. Jälkilöylyt huomioidaan lämmityksessä. Perushinta sisältää 6 osallistujaa, sen jälkeen 10 €/hlö. Hinnat ovat voimassa ainoastaan yksityishenkilöille; yrityksille omat tuotteet.',null,180.0,'from','Alkaen 180,00 € / 2 h',25.5,6,10.0,120,'2 h (ma–to klo 19–21), 3 h (pe–su klo 19–22)',1,null,1,true,true),
(27,'johku','63','perinnesaunotus-jalkiloylyille','Perinnesaunotus jälkilöylyille',null,'ceremony','Saunottajan palvelut omalle porukalle jälkilöylyille. Valitse yksi kolmesta: 1) ohjattu ryhmäsaunaseremonia (ryhmävihdonta, yrttilöylyt, saunaloitsut, vihtapesu); 2) ohjatut minisaunahoidot koko porukalle tarvikkeineen; 3) opastus vihdontaperinteeseen ja itsevihdontaan (muutama vihta mukana). Halutessa ohjattu löylyntervehdys. Hinta sisältää saunottajan palvelut 1–8 hengelle; isommat ryhmät: savusauna@saunotus.fi.',null,150.0,'per_hour','150,00 € / h',13.5,null,null,60,'1 h',1,8,2,true,true),
(28,'johku','116','perinnesaunotus-yksityisvuorolle','Perinnesaunotus yksityisvuorolle',null,'ceremony','Saunottajan palvelut omalle yksityisvuorolle (samat kolme vaihtoehtoa kuin jälkilöylyille). Seremonian kesto 1–8 hengelle noin 1,5 h ja 9–16 hengelle 2 h. Hinta sisältää vain saunottajan palvelut, ei saunan vuokraa.',null,350.0,'from','Alkaen 350,00 € / h',13.5,null,null,90,'n. 1,5 h (1–8 hlö), 2 h (9–16 hlö)',1,16,2,true,true),
(29,'johku','102','morsiussauna','Morsiussauna','Bridal sauna','ceremony','Morsiamelle mahdollisuus hiljentyä, päästää irti menneestä ja valmistautua uuteen elämänvaiheeseen. Ohjattu saunaseremonia: opastus morsiussaunaperinteeseen, seremoniavihdonta morsiamelle, ruusukuorinta, yrttilöylyt, lemmenloitsuja ja morsiustaikoja toiveiden mukaan. Seremonian kesto n. 1 h, jonka jälkeen voi jäädä viettämään iltaa omalla porukalla. Morsiussaunan tekee aina naispuolinen saunottaja. Maksimiosallistujamäärä 8 hlö; isommat ryhmät sähköpostitse savusauna@saunotus.fi.',null,390.0,'from','Alkaen 390,00 € / 3 h',25.5,null,null,180,'seremonia n. 1 h, varaus 3 h',1,8,2,true,true),
(30,'johku','108','synttarisauna','Synttärisauna','Birthday sauna ceremony','ceremony','Syntymäpäivän saunotus: pestään pois vanha ja turha, tasapainotetaan ja annetaan voimaa tulevaan vuoteen. Sisältää ohjatun saunaseremonian, toiveiden mukaan vihdontaa tai minihoitoja sekä löylyn luontia ja lempeää ilmavihdontaa. Seremonian kesto n. 1 h. Seremonian jälkeen voi nauttia maasavusaunan löylyistä sekä kylmä- ja lämminpaljuista. Maksimiosallistujamäärä 8 hlö; isommat ryhmät: savusauna@saunotus.fi.',null,350.0,'from','Alkaen 350,00 € / 2 h',25.5,null,null,120,'seremonia n. 1 h; varaus 2–3 h',1,8,2,true,true),
(31,'johku','107','turvesauna','Turvesauna','Peat sauna','ceremony','Turvesaunaseremonia ryhmälle: ohjattu ensilöylyseremonia, saunottajan ohjaama kokovartaloturvehoito sekä löylyn luontia ja lempeää ilmavihdontaa. Turve imee epäpuhtauksia iholta ja hoitaa ihoa, päänahkaa ja hiuspohjaa. Seremonian kesto n. 1 h. Seremonian jälkeen voi nauttia maasavusaunan löylyistä sekä kylmä- ja lämminpaljuista. Maksimiosallistujamäärä 8 hlö; isommat ryhmät: savusauna@saunotus.fi.',null,330.0,'from','Alkaen 330,00 € / 2 h',25.5,null,null,120,'seremonia n. 1 h; varaus 2–3 h',1,8,2,true,true),
(32,'johku','67','naisten-joulusauna','Naisten jouluinen saunailta',null,'event','Saunan naisten (Laura ja Saara) ohjaama jouluinen saunailta: savusaunan löylyt, kylmä- ja lämminvesipaljut, alku- ja loppujuomat, havuinen löylyvesi, lempeää vihdontaa, löylyn tervehdysseremonia, pientä purtavaa, pellavaiset laudeliinat ja saunahoitoja. Saavu omassa tahdissa, kuitenkin klo 16.45 mennessä; saunotus alkaa klo 17.',null,69.0,'per_person','69,00 € / hlö',25.5,null,null,180,'pe 18.12.2026 klo 16–19',1,8,2,true,true),
(33,'johku','211','sipoonjoen-kekri','Sipoonjoen Kekri',null,'event','Kekrijuhla pyhäinpäivänä 31.10.2026: kekritulet, sadonkorjuun antimet ja saunottajien ohjaama, tavallista pidempi kekrisauna rituaalisauna Raunissa (yrttihoidot, havuilla luotu löyly edesmenneille). Hintaan sisältyy pitkä kekrisaunotus, kevyt sadonkorjuuiltapala, ohjattu kekritulirituaali ja vapaata yhdessäoloa. Ota mukaan saunatarpeet (kylpytakki, pyyhe, lipokkaat, halutessa uima-asu, saunajuoma), lämmintä vaatetta, pieni lahja edesmenneille ja halutessa jotain yhteiseen pöytään.',null,79.0,'per_person','79,00 € / hlö',25.5,null,null,240,'31.10.2026, n. 4 h',1,8,3,true,true),
(34,'johku','159','saunottajien-yhteisopaiva-2','Saunottajien yhteisöpäivä',null,'event','Yhteisöpäivä Terve Löyly -saunottajakoulutuksen käyneille saunottajille 20.2.2027 klo 11–20: syventäviä teemoja, saunottajan polun haasteita ja toinen toistensa hoitamista. Hinta sisältää saunottajien ohjauksen, lämpimät saunat, saunotustarvikkeet, yrttiteetä ja pientä purtavaa.',null,69.0,'per_person','69 € / hlö',25.5,null,null,540,'20.2.2027 klo 11–20',null,8,1,true,true),
(35,'johku','177','saunottajakoulutus-syksy-2026','Saunottajakoulutus - Syksy 2026 (varausmaksu)',null,'training','Terve Löyly -saunottajakoulutus: lähiopetusta kuutena viikonloppuna (pe klo 19–22 seremonia savusaunassa; la–su klo 9–16: teoria 9–13, käytännön havainnollistus 13.30–14.30, harjoittelu hoito-/telttasaunassa 14.30–16) sekä ohjattua asiakastyöharjoittelua yleisten vuorojen yhteydessä. Koulutuksen hinta 2400 €; sisältää lähiviikonloput savusaunaelämyksineen ja saunotusharjoittelun, ei ruokailuja eikä majoitusta. Paikka varataan maksamalla varausmaksu 200 €, joka vähennetään loppusummasta. Lisätiedot: https://saunakoulutus.fi/ Ajankohta 4.9.2026–16.5.2027. Tila verkkokaupassa: Loppuunmyyty.',null,200.0,'deposit','200,00 € varausmaksu (koulutus 2400 €)',25.5,null,null,null,'6 viikonloppua 4.9.2026–16.5.2027',null,null,1,false,true),
(36,'johku','210','saunottajakoulutus-kevat-syksy-2027','Saunottajakoulutus - kevät & syksy 2027 (varausmaksu)',null,'training','Terve Löyly -saunottajakoulutus: lähiopetusta kuutena viikonloppuna (pe klo 19–22 seremonia savusaunassa; la–su klo 9–16: teoria 9–13, käytännön havainnollistus 13.30–14.30, harjoittelu hoito-/telttasaunassa 14.30–16) sekä ohjattua asiakastyöharjoittelua yleisten vuorojen yhteydessä. Koulutuksen hinta 2400 €; sisältää lähiviikonloput savusaunaelämyksineen ja saunotusharjoittelun, ei ruokailuja eikä majoitusta. Paikka varataan maksamalla varausmaksu 200 €, joka vähennetään loppusummasta. Lisätiedot: https://saunakoulutus.fi/ Ajankohtaa ei ilmoitettu tuotesivulla.',null,200.0,'deposit','200,00 € varausmaksu (koulutus 2400 €)',25.5,null,null,null,null,null,null,1,false,true),
(37,'johku','158','saunottajakoulutus-kevat-2026','Saunottajakoulutus - Kevät 2026 (varausmaksu)',null,'training','Varausmaksu kevään 2026 saunottajakoulutukseen. Tuotesivulla ei kuvausta.',null,200.0,'deposit','200,00 €',25.5,null,null,null,null,null,null,1,null,false),
(38,'johku','29','lahjakortti','Avoin lahjakortti','Gift Card','gift_card','Arvolahjakortti, jonka arvon voi valita vapaasti välillä 29–500 € (ehdotukset 29 €, 250 €, 500 €). Ei sidottu tiettyyn tuotteeseen; käy kaikkiin palveluihin ja sillä voi maksaa osan arvokkaammasta elämyksestä. Voimassa kuusi kuukautta ostohetkestä; voidaan toimittaa suoraan vastaanottajalle. Jos lahjakorttia ei ehditä käyttää, voimassaoloa voi pyytää jatkamaan maksutta sähköpostitse tai puhelimitse – toivomaasi päivään asti tai muuten 3 kuukautta eteenpäin.',null,58.0,'variable','Vapaavalintainen 29,00–500,00 € (oletus 58,00 €)',25.5,null,null,null,null,null,null,null,null,true),
(39,'johku','196','savusaunaelamys-ja-koivuvihta','Savusaunaelämys ja koivuvihta -lahjakortti',null,'gift_card','Lahjakortti: paikka yleiselle saunavuorolle ja valmiiksi liotettu koivuvihta.',null,42.0,'fixed','42,00 €',25.5,null,null,null,null,1,1,null,true,true),
(40,'johku','64','paikka-yleiselle-vuorolle-ja-saunahoito','Savusaunaelämys ja saunahoito -lahjakortti',null,'gift_card','Lahjakortti: paikka yleiselle saunavuorolle sekä 60 min vapaavalintainen hoito yhdelle. Hoidon yhteydessä savusauna, kylmä- ja lämminvesialtaat ja nuotiopaikka.',null,128.0,'fixed','128,00 €',25.5,null,null,null,null,1,1,3,true,true),
(41,'johku','115','savusaunaelamys-ja-vihtahoito-kahdelle-lahjakortti','Savusaunaelämys ja saunahoito kahdelle -lahjakortti',null,'gift_card','Lahjakortti kahdelle: paikat yleiselle saunavuorolle ja 60 minuutin saunahoito kahdelle.',null,192.0,'fixed','192,00 €',25.5,null,null,null,null,2,2,3,true,true),
(42,'johku','169','savusaunaelamys-turvenaamiolla-ja-jalkakylvylla-kahdelle','Savusaunaelämys turvenaamiolla ja jalkakylvyllä kahdelle',null,'gift_card','Lahjakortti kahdelle: paikat yleiselle vuorolle, turvenaamio ja jalkakylpy (merisuola ja saunan ympäristöstä poimitut yrtit); hoidot tehdään omatoimisesti saunomisen yhteydessä.',null,88.0,'fixed','88,00 €',25.5,null,null,null,null,2,2,null,true,true),
(43,'johku','31','vuosikortti','Vuosikortti',null,'season_card','Rajattomat yleiset saunavuorot vuoden ajan. Henkilökohtainen, ei siirrettävissä. Voimassa yhden vuoden ostopäivästä. Käytettävissä kaikilla yleisillä vuoroilla, ei turvetorstaina tai muissa seremonioissa. Vuoro varattava etukäteen; vain yksi varaus voi olla kerrallaan voimassa.',null,290.0,'fixed','290,00 €',25.5,null,null,null,'1 vuosi',1,1,2,true,true),
(44,'johku','103','saunavihta','Saunavihta','Saunavihta (birch whisk)','product_rental','Koivusta valmistettu saunavihta, tarjoillaan liotettuna ja valmiina vihdontaan; ennakkoon tilatut vihdat valmistellaan saunavuoroa varten.',null,13.0,'per_unit','13,00 €',25.5,null,null,null,null,null,null,null,null,true),
(45,'johku','113','jalkakylpy-ja-turvenaamio','Jalkakylpy ja turvenaamio',null,'product_rental','Omatoiminen turvenaamio ja jalkakylpy (kylpysuola-yrttisekoitus) saunomisen yhteydessä.',null,15.0,'per_unit','15,00 €',25.5,null,null,null,null,null,null,null,null,true),
(46,'johku','117','pyyhe-vuokralle','Pyyhe vuokralle','Rental towel','product_rental','Pellavainen vuokrapyyhe.',null,5.0,'per_unit','5,00 € / vrk',25.5,null,null,null,null,null,null,null,null,true),
(47,null,null,'tossut-saunatakki-vuokra','Tossujen tai saunatakin vuokra (paikan päällä)',null,'product_rental','Paikan päältä voi vuokrata tai ostaa pyyhkeen, saunatakin tai tossut. Verkkokaupan tuotesivuilla: pyyhe- ja tossuvuokra 5 €. Vanhan sivuston mukaan 5 € / pyyhe, saunatakki tai tossut.',null,5.0,'per_unit','5 € / kpl',null,null,null,null,null,null,null,null,null,true),
(48,'johku','17','saunavuoro-yrityksille','Savusaunavuoro yrityksille',null,'corporate','Työporukalle ryhmäytymiseen ja rentoutumiseen. Käytössä savusauna, lämmin palju, kylmävesiallas, laavu ja hirsimökki. Hinta sisältää 2 kpl valmiiksi liotettuja koivuisia saunavihtoja. ALV 25,5 %. Perjantaisin kaksi varausaikaa: 12–21 tai 16–21; koko päivän varauksessa sauna käytettävissä klo 14 alkaen.',null,350.0,'from','Alkaen 350,00 € / 2 h',25.5,null,null,120,'2 h / 5 h / 9 h',null,null,1,true,true),
(49,'johku','41','jalkiloylyt-yrityksille','Savusaunan jälkilöylyt yrityksille',null,'corporate','Omalla firman porukalla jälkilöylyihin yleisten vuorojen jälkeen klo 19 alkaen. Sisältää savusaunan, lämmin- ja kylmävesialtaat sekä laavun vapaan käytön. Laavulla voi olla vielä ihmisiä klo 19–20.',null,250.0,'from','Alkaen 250,00 € / 2 h',25.5,null,10.0,120,'2–3 h',null,null,1,true,true),
(50,null,null,'yrityspaivat','Työhyvinvointipäivät ja ryhmät (tarjouspyyntö)','Company & group days','corporate','Savusauna tarjoaa ympäristön työhyvinvointipäiville, pienryhmille ja yhteisille saunailloille. Saunavuorojen, rituaalien ja hoitojen lisäksi päivään voidaan yhdistää esim. metsäkävely, metsäjooga, eräruokailu laavulla tai vihdansidontatyöpaja. Hinnat tarjouspyynnöstä.',null,null,'variable','Pyydä tarjous',null,null,null,null,null,null,null,1,null,true);
